    startGenerate(id) { this.showGenMacroModal(id); },
    async confirmGenerate(id) { const $ = getJQuery(); const prompt = theaterData.prompts.find(p => p.id === id); if (!prompt) return; const charVal = $('#tm-genMacroChar').val(); const userVal = $('#tm-genMacroUser').val(); const processedContent = replaceMacros(prompt.content, charVal, userVal); this.closeGenMacroModal(); currentGenerationPromptId = id; $('#tm-genPromptList').hide(); $('#tm-genResultArea').show(); $('#tm-genResultActions').hide(); $('#tm-genResultContent').html(`<div class="tm-gen-loading"><div class="tm-gen-loading-spinner"></div><p>正在演绎中...</p><p class="tm-gen-loading-tip">「${escapeHtml(prompt.title)}」</p></div>`); isGenerating = true; try { const result = await triggerSlashWithResult(`/gen lock=on ${processedContent}`); isGenerating = false; if (result) { theaterData.generationHistory = theaterData.generationHistory || []; theaterData.generationHistory.unshift({ promptId: id, promptTitle: prompt.title, input: processedContent, output: result, time: Date.now() }); theaterData.generationHistory = theaterData.generationHistory.slice(0, 50); await saveData(); this.recordUsage(id); $('#tm-genResultContent').html(`<div class="tm-gen-success"><div class="tm-gen-success-header"><span class="tm-gen-success-icon">✨</span><span>演绎完成</span></div><div class="tm-gen-output-box">${escapeHtml(result)}</div></div>`); $('#tm-genResultActions').show(); getParentWindow()._tmLastGenResult = result; getParentWindow()._tmLastGenPromptTitle = prompt.title; } else { $('#tm-genResultContent').html(`<div class="tm-gen-error"><span class="tm-gen-error-icon">⚠️</span><p>演绎失败或返回为空</p></div>`); } } catch (e) { isGenerating = false; $('#tm-genResultContent').html(`<div class="tm-gen-error"><span class="tm-gen-error-icon">❌</span><p>演绎出错</p></div>`); } },
    backToList() { const $ = getJQuery(); $('#tm-genResultArea').hide(); $('#tm-genPromptList').show(); currentGenerationPromptId = null; },
    async copyResult() { const result = getParentWindow()._tmLastGenResult; if (result) { await copyToClipboard(result); alert('✅ 已复制'); } },
    async insertResultToInput() { const result = getParentWindow()._tmLastGenResult; if (result) { await triggerSlash(`/setinput ${result}`); this.closeModal(); } },
    saveResultToMemory() { const result = getParentWindow()._tmLastGenResult; const promptTitle = getParentWindow()._tmLastGenPromptTitle || '演绎结果'; if (result) this.openSaveMemoryModal(result, 'generation', { promptTitle }); },
    viewResultFullscreen() { const result = getParentWindow()._tmLastGenResult; const promptTitle = getParentWindow()._tmLastGenPromptTitle || '演绎结果'; if (result) showFullscreenViewer(`🎬 ${promptTitle}`, `<div style="white-space:pre-wrap;line-height:1.6;">${escapeHtml(result)}</div>`, null); },
