  // ========== 初始化 ==========
  async function initData() { await loadData(); if (theaterData.prompts.length === 0 && theaterData.memories.length === 0) { await checkBackupRestore(); } await updateCurrentInfo(); TheaterManager.updateCategoryFilter(); TheaterManager.renderPromptList(); }

  function initIntegration() { const $ = getJQuery(); if (!$) { setTimeout(initIntegration, 500); return; } $('#theater-manager-menu-item').remove(); const extensionsMenu = $('#extensionsMenu'); if (!extensionsMenu.length) { setTimeout(initIntegration, 500); return; } extensionsMenu.append(`<a id="theater-manager-menu-item" class="list-group-item" href="#" title="小剧场管理器"><i class="fa-solid fa-theater-masks"></i> 小剧场管理器</a>`); $('#theater-manager-menu-item').on('click', function(e) { e.preventDefault(); e.stopPropagation(); $('#extensionsMenu').fadeOut(200); createTheaterManagerUI(); }); injectCollectButtonStyles(); setupChatObserver(); setupCollectButtonHandler(); console.log('✅ 小剧场管理器 v5.0 已加载'); }

  function start() { const $ = getJQuery(); if ($ && $('#extensionsMenu').length) initIntegration(); else setTimeout(start, 500); }

